typedef float rational_t;
typedef unsigned char uint8;

class stringx
{
public:
  char *chars;
  void *my_buf;
  stringx();
  stringx(const stringx &);
  ~stringx();
  stringx &operator=(const stringx &);
  stringx &operator=(const char *);
};

struct color
{
  float r, g, b, a;
};

enum text_widget_justification
{
  JUSTIFY_LEFT
};

class typeface_def
{
public:
  void load();
};

typeface_def *typeface_open(const stringx &fname);
stringx localize_text_safe(stringx src);

class widget
{
public:
  enum widget_type_e
  {
    WTYPE_Bitmap,
    WTYPE_Text,
    WTYPE_TextBlock
  };

  enum rhw_layer_e
  {
    RHW0,
    RHW1,
    RHW2,
    RHW3,
    RHW4,
    RHW5,
    RHW6,
    RHW7,
    RHW8,
    RHW9,
    RHW_OVER_PFE1,
    RHW_OVER_PFE2,
    NUM_RHW_LAYERS
  };

  widget(const char *_widget_name, widget *_parent, short _x, short _y);
  virtual ~widget();

protected:
  stringx widget_name;
  widget_type_e type;
  char remainder[308];
  static rhw_layer_e rhw_2d_layer;
  static rational_t rhw_2d_val[NUM_RHW_LAYERS];
};

class text_block_widget : public widget
{
public:
  class block_info_t
  {
  public:
    rational_t scale;
    text_widget_justification just;
    stringx typeface;
    uint8 max_lines;
    short line_spacing;
    short max_width;
    stringx break_substring;
    stringx text;
    color col;
  };

  text_block_widget(const char *_widget_name, widget *_parent, short _x, short _y, block_info_t *info_ptr);
  virtual ~text_block_widget();

protected:
  void fill_lines();
  block_info_t block_info;
  uint8 num_lines_used;
  rational_t first_rhw;
  typeface_def *text_font;
};

#define WIDGET_RHW_INC 1.0f

text_block_widget::text_block_widget( const char *_widget_name, widget *_parent, short _x, short _y, block_info_t *info_ptr )
  : widget( _widget_name, _parent, _x, _y )
{
  type = WTYPE_TextBlock;
  block_info = *info_ptr;

  num_lines_used = 0;
  stringx temp = localize_text_safe( block_info.text );
  block_info.text = temp;

  // reserve block of rhws based on max_lines
  first_rhw = widget::rhw_2d_val[rhw_2d_layer];
  widget::rhw_2d_val[rhw_2d_layer] += block_info.max_lines * WIDGET_RHW_INC;

  text_font = NULL;
  text_font = typeface_open(block_info.typeface);
  text_font->load();

  fill_lines();
}
